query CurrentUser {
  currentUser {
    eid name email
    organizations {
      eid slug name
      casts { eid eidStatic name }
      welds { eid slug name }
      forges { eid slug name }
    }
  }
}

query Organization($organizationSlug: String, $organizationEid: String) {
  organization(slug: $organizationSlug, eid: $organizationEid) {
    eid slug name
    casts { eid eidStatic name }
    welds { eid slug name }
    forges { eid slug name }
  }
}

mutation CreateEtchPacket(
  $name: String, $files: [JSON!], $signers: [JSON!], $data: JSON,
  $isDraft: Boolean, $isTest: Boolean, $signatureEmailSubject: String,
  $signatureEmailBody: String, $signaturePageOptions: JSON,
  $webhookURL: String, $replyToName: String, $replyToEmail: String,
  $mergePDFs: Boolean, $allowUpdates: Boolean
) {
  createEtchPacket(
    name: $name, files: $files, signers: $signers, data: $data,
    isDraft: $isDraft, isTest: $isTest,
    signatureEmailSubject: $signatureEmailSubject,
    signatureEmailBody: $signatureEmailBody,
    signaturePageOptions: $signaturePageOptions,
    webhookURL: $webhookURL, replyToName: $replyToName,
    replyToEmail: $replyToEmail, mergePDFs: $mergePDFs,
    allowUpdates: $allowUpdates
  ) {
    eid name status detailsURL
    documentGroup { eid status files }
    signers { eid aliasId name email status signActionType }
  }
}

query EtchPacket($eid: String!) {
  etchPacket(eid: $eid) {
    eid name status detailsURL isTest completedAt
    documentGroup { eid status files downloadZipURL }
    signers { eid aliasId name email status signActionType routingOrder }
  }
}

mutation SendEtchPacket($eid: String!) {
  sendEtchPacket(eid: $eid) {
    eid status detailsURL
    signers { eid name email status }
  }
}

mutation UpdateEtchPacket($eid: String!, $payload: JSON, $mergePayloads: Boolean) {
  updateEtchPacket(eid: $eid, payload: $payload, mergePayloads: $mergePayloads) {
    eid status
  }
}

mutation GenerateEtchSignURL($signerEid: String!, $clientUserId: String!) {
  generateEtchSignURL(signerEid: $signerEid, clientUserId: $clientUserId)
}

query Signer($eid: String!) {
  signer(eid: $eid) {
    eid aliasId name email status signActionType routingOrder
  }
}

mutation UpdateSigner($eid: String!, $name: String, $email: String, $activateIfPending: Boolean) {
  updateSigner(eid: $eid, name: $name, email: $email, activateIfPending: $activateIfPending) {
    eid name email status
  }
}

mutation ExpireSignerTokens($signerEid: String!) {
  expireSignerTokens(signerEid: $signerEid) { eid status }
}

query Cast($eid: String!, $versionNumber: Int) {
  cast(eid: $eid, versionNumber: $versionNumber) {
    eid eidStatic name title config isTemplate versionNumber
  }
}

query Weld($eid: String, $slug: String, $organizationSlug: String, $versionNumber: Int) {
  weld(eid: $eid, slug: $slug, organizationSlug: $organizationSlug, versionNumber: $versionNumber) {
    eid slug name
    forges { eid slug name }
  }
}

query WeldData($eid: String!) {
  weldData(eid: $eid) {
    eid isTest isComplete createdAt
    submissions { eid completedAt payload forge { eid slug name } }
    documentGroup { eid status files }
  }
}

query Forge($eid: String, $eidOrSlug: String, $organizationSlug: String, $versionNumber: Int) {
  forge(eid: $eid, eidOrSlug: $eidOrSlug, organizationSlug: $organizationSlug, versionNumber: $versionNumber) {
    eid slug name config versionNumber
  }
}

mutation CreateWebhook($url: String!, $organizationEid: String, $enabled: Boolean) {
  createWebhook(url: $url, organizationEid: $organizationEid, enabled: $enabled) {
    eid url enabled
  }
}
